                        &&& actual_replicas[i as int].wf()
                        &&& actual_replicas[i as int].spec_id() == i
                        &&& actual_replicas[i as int].unbounded_log_instance@
                            == unbounded_log_instance
                        &&& actual_replicas[i as int].cyclic_buffer_instance@
                            == cyclic_buffer_instance
                    },
