                    #![trigger replicas[i]]
                    idx <= i < num_replicas ==> {
                        &&& #[trigger] replicas.contains_key(i)
                        &&& replicas[i].instance_id() == unbounded_log_instance.id()
                        &&& replicas[i].key() == i
                        &&& replicas[i].value() == DT::init_spec()
                    }),
